#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "text_editor.h"
#include "text_ops.h"
#include "cursor_nav.h"
#include "file_ops.h"
#include "display_search.h"
#include "redo_undo.h"
static void input(const char*prompt,char*b,size_t n){printf("%s",prompt);if(!fgets(b,(int)n,stdin)){b[0]=0;return;}b[strcspn(b,"\n")]=0;}
static int number(const char*prompt){char b[80],*end;long v;input(prompt,b,sizeof b);v=strtol(b,&end,10);if(end==b||*end||v<1||v>2147483647L)return -1;return (int)v;}
static void menu(void){puts("\n===== CONSOLE TEXT EDITOR =====");puts("1 Insert line  2 Insert characters  3 Delete characters");puts("4 Delete line  5 Cursor navigation  6 Search  7 Replace");puts("8 Copy  9 Cut  10 Paste  11 Undo  12 Redo");puts("13 Open file  14 Save file  15 Display  16 Cursor position  17 Exit");}
int main(void){TextEditor e;char a[2048],b[2048],name[512];int c;if(!initializeEditor(&e)){puts("Initialization failed.");return 1;}for(;;){menu();c=number("Choice: ");switch(c){case 1:{int line=number("Insert before line (1..N+1): ");input("Line text: ",a,sizeof a);puts(insertLineAtPosition(&e,a,line)?"Line inserted.":"Insert failed.");break;}case 2:{int l=number("Line: "),p=number("Position (1-based): ");input("Text: ",a,sizeof a);puts(insertCharacters(&e,l,p,a)?"Inserted.":"Insert failed.");break;}case 3:{int l=number("Line: "),p=number("Start position: "),n=number("Count: ");puts(deleteCharacters(&e,l,p,n)?"Deleted.":"Delete failed.");break;}case 4:{int l=number("Line to delete: ");puts(deleteLine(&e,l)?"Line deleted.":"Delete failed.");break;}case 5:{int d=number("1 Left 2 Right 3 Up 4 Down 5 Start-line 6 End-line 7 Start-file 8 End-file: ");switch(d){case 1:moveCursorLeft(&e);break;case 2:moveCursorRight(&e);break;case 3:moveCursorUp(&e);break;case 4:moveCursorDown(&e);break;case 5:jumpToStartOfLine(&e);break;case 6:jumpToEndOfLine(&e);break;case 7:jumpToStartOfFile(&e);break;case 8:jumpToEndOfFile(&e);break;default:puts("Invalid direction.");}showCursorPosition(&e);break;}case 6:input("Search text: ",a,sizeof a);findText(&e,a);break;case 7:input("Old text: ",a,sizeof a);input("New text: ",b,sizeof b);printf("Replaced: %d\n",replaceText(&e,a,b));break;case 8:case 9:{int l=number("Line: "),p=number("Start position: "),n=number("Character count: ");char*x=c==8?copyText(&e,l,p,n):cutText(&e,l,p,n);if(!x)puts("Clipboard operation failed.");else{free(e.clipboard);e.clipboard=x;printf("Clipboard: %s\n",x);}break;}case 10:{int l=number("Line: "),p=number("Paste position: ");puts(e.clipboard&&pasteText(&e,l,p,e.clipboard)?"Pasted.":"Paste failed or clipboard empty.");break;}case 11:puts(undo(&e)?"Undo successful.":"Nothing to undo.");break;case 12:puts(redo(&e)?"Redo successful.":"Nothing to redo.");break;case 13:input("Filename: ",name,sizeof name);puts(openFile(&e,name)?"File opened.":"Open failed.");break;case 14:input("Filename: ",name,sizeof name);puts(saveFile(&e,name)?"File saved.":"Save failed.");break;case 15:displayText(&e);break;case 16:showCursorPosition(&e);break;case 17:destroyEditor(&e);puts("Goodbye. Memory released.");return 0;default:puts("Invalid choice.");}}}
